import sys, importlib, pandas as pd, itertools
OUT=['transactionCategory','transactionSubcategory','partyName']
def load(path):
    for m in list(sys.modules):
        if m.startswith('categorizationapp'): del sys.modules[m]
    sys.path.insert(0,path)
    m = importlib.import_module('categorizationapp.BankScripts.HDFC')
    sys.path.remove(path); return m

# sequences of 3 rows: types x amounts x description-ids
descs = {'A':'NEFT PAYMENT TO ABC','B':'NEFT PAYMENT TO XYZ','C':'ACH D- BD-ACME-12'}
rows=[]
for combo in itertools.product('AB', repeat=3):
    for types in itertools.product(['DEBIT','CREDIT'], repeat=3):
        for amts in itertools.product([100.0,200.0], repeat=3):
            rows.append((combo,types,amts))
def frame(c,t,a):
    return pd.DataFrame([{'description':descs[c[i]],'remark':'','type':t[i],'amount':a[i],
                          'balanceAfterTransaction':1000.0} for i in range(3)])
oldm, newm = load('/tmp/opencode/orig/categorizationapp'), load('/app/categorizationapp')
ndiff=0
for c,t,a in rows:
    o = oldm.categorize_HDFC_transactions(frame(c,t,a),'SAVING')[OUT]
    n = newm.categorize_HDFC_transactions(frame(c,t,a),'SAVING')[OUT]
    d = (o!=n).any(axis=1)
    if d.any():
        ndiff+=1
        for i in d[d].index:
            print(c,t,a,'row',i,tuple(o.loc[i]),'->',tuple(n.loc[i]))
print('sequences with diffs:', ndiff, 'of', len(rows))
